struct Point { int x, y; };
struct Rectangle {
    struct Point topLeft;
    struct Point bottomRight;
};

int main(void) {
    struct Rectangle rect = {{0, 10}, {20, 0}};
    struct Rectangle *p = &rect;

    int width = p->bottomRight.x - p->topLeft.x;
    int height = p->topLeft.y - p->bottomRight.y;
    printf("Area: %d\n", width * height); // Area: 200
    return 0;
}

